def transform(grid):
    # Reflect the three colored cells about the main diagonal, preserving color.
    n = len(grid)
    out = [[0]*len(grid[0]) for _ in range(len(grid))]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                if c < n and r < len(row):
                    out[c][r] = v
                else:
                    out[r][c] = v
    return out
